1	<script>
2	  // ========== 日志系统（直接操作 storage）==========
3	  var LOG_KEY = 'app_runtime_logs'
4	  var MAX_LOGS = 30
5	  var logQueue = []
6	  
7	  // 导入 storage（注意：需要在函数内部 require）
8	  function getStorage() {
9	    return require('@system.storage')
10	  }
11	  
12	  // 保存日志到 storage
13	  function saveLogsToStorage() {
14	    try {
15	      var storage = getStorage()
16	      storage.set({
17	        key: LOG_KEY,
18	        value: JSON.stringify(logQueue.slice(0, MAX_LOGS))
19	      })
20	    } catch(e) {
21	      console.log('日志保存失败:', e)
22	    }
23	  }
24	  
25	  // 加载已有日志
26	  function loadLogsFromStorage() {
27	    try {
28	      var storage = getStorage()
29	      storage.get({
30	        key: LOG_KEY,
31	        success: function(data) {
32	          try {
33	            var saved = JSON.parse(data)
34	            if (saved && saved.length) {
35	              logQueue = saved
36	            }
37	          } catch(e) {}
38	        },
39	        fail: function() {}
40	      })
41	    } catch(e) {}
42	  }
43	  
44	  // 初始化：加载已有日志
45	  loadLogsFromStorage()
46	  
47	  // 添加日志
48	  global.addRuntimeLog = function(msg, level) {
49	    var now = new Date()
50	    var time = now.getHours().toString().padStart(2,'0') + ':' + 
51	               now.getMinutes().toString().padStart(2,'0') + ':' + 
52	               now.getSeconds().toString().padStart(2,'0')
53	    
54	    logQueue.unshift({
55	      time: time,
56	      msg: msg,
57	      level: level || 'info'
58	    })
59	    
60	    if (logQueue.length > MAX_LOGS) {
61	      logQueue.pop()
62	    }
63	    
64	    // 立即保存
65	    saveLogsToStorage()
66	    
67	    // 控制台输出
68	    console.log('[' + (level || 'info').toUpperCase() + '] ' + msg)
69	  }
70	  
71	  // 获取所有日志
72	  global.getRuntimeLogs = function() {
73	    return logQueue
74	  }
75	  
76	  // 清空日志
77	  global.clearRuntimeLogs = function() {
78	    logQueue = []
79	    saveLogsToStorage()
80	  }
81	  
82	  // 记录应用启动
83	  global.addRuntimeLog('应用启动', 'info')
84	  
85	  // ========== 防抖锁 ==========
86	  export default {
87	    isNavigating: false,
88	
89	    safeNavigate(fn) {
90	      if (this.isNavigating) return
91	      this.isNavigating = true
92	      fn()
93	      setTimeout(() => { this.isNavigating = false }, 300)
94	    }
95	  }
96	</script>

