315	    // 主逻辑
316	    // ============================================================
317	    async onInit() {
318	  var self = this
319	  var id = global.selectedEventId
320	  this.eventId = id
321	
322	  if (typeof global.addRuntimeLog === 'function') {
323	    global.addRuntimeLog('[detail] 打开 ID=' + id, 'info')
324	  }
325	
326	  if (id === undefined || id === null) {
327	    this.errorMsg = '事件ID无效'
328	    this.loading = false
329	    return
330	  }
331	
332	  this.checkFavoriteStatus(id)
333	
334	  // ==========================================================
335	  // 获取 Map 数据
336	  // ==========================================================
337	  var mapData = null
338	
339	  // 第一步：尝试从引擎获取（300ms 超时）
340	  try {
341	    var engineResult = await Promise.race([
342	      global.getItemById(id),
343	      new Promise(function(resolve) {
344	        setTimeout(function() {
345	          resolve(null)
346	        }, 300)
347	      })
348	    ])
349	    if (engineResult) {
350	      mapData = engineResult
351	      if (typeof global.addRuntimeLog === 'function') {
352	        global.addRuntimeLog('[detail] 引擎获取 Map 成功（内存命中）', 'info')
353	      }
354	    }
355	  } catch(e) {
356	    if (typeof global.addRuntimeLog === 'function') {
357	      global.addRuntimeLog('[detail] 引擎获取异常: ' + e.message, 'warn')
358	    }
359	  }
360	
361	  // 第二步：引擎超时或失败 → 从缓存加载 Map 到内存
362	  if (!mapData) {
363	    if (typeof global.addRuntimeLog === 'function') {
364	      global.addRuntimeLog('[detail] 引擎未命中，尝试从缓存加载 Map', 'info')
365	    }
366	    var loaded = await this._loadMapFromCache(id)
367	    if (loaded) {
368	      // 缓存加载成功 → 再试一次引擎
369	      try {
370	        var result2 = await global.getItemById(id)
371	        if (result2) {
372	          mapData = result2
373	          if (typeof global.addRuntimeLog === 'function') {
374	            global.addRuntimeLog('[detail] 缓存加载后引擎获取成功', 'success')
375	          }
376	        }
377	      } catch(e) {}
378	    }
379	  }
380	
381	  // 第三步：缓存也没有 → 直接读文件（兜底）
382	  if (!mapData) {
383	    if (typeof global.addRuntimeLog === 'function') {
384	      global.addRuntimeLog('[detail] 缓存也没有，直接读 Map 文件', 'warn')
385	    }
386	    mapData = await this._readMapFileDirectly(id)
387	    if (mapData) {
388	      if (typeof global.addRuntimeLog === 'function') {
389	        global.addRuntimeLog('[detail] 直接读 Map 文件成功', 'success')
390	      }
391	    }
392	  }
393	
394	  if (!mapData) {
395	    this.errorMsg = '未找到数据 (ID=' + id + ')'
396	    this.loading = false
397	    return
398	  }
399	
400	  // 填充基础信息
401	  this.yearDisplay = mapData.yearDisplay || '未知'
402	  this.region = mapData.region || '未知'
403	  this.detailTitle = mapData.title || '未知事件'
404	  var fullKeywordList = [this.detailTitle]
405	
406	  // ==========================================================
407	  // 读 detail 文件
408	  // ==========================================================
409	  var detailData = await this._readDetailFileDirectly(id)
410	  if (detailData) {
411	    if (detailData.restKeywords && detailData.restKeywords.length > 0) {
412	      fullKeywordList = fullKeywordList.concat(detailData.restKeywords)
413	    }
414	    this.cause = detailData.cause || ''
415	    this.impact = detailData.impact || ''
416	  } else {
417	    this.cause = ''
418	    this.impact = ''
419	  }
420	
421	  this.keywordList = fullKeywordList
422	  this.loading = false
423	
424	  if (typeof global.addRuntimeLog === 'function') {
425	    global.addRuntimeLog('[detail] 加载完成', 'info')
426	  }
427	},
428	
429	    // ============================================================
430	    // 从 storage 缓存加载 Map 到内存
431	    // ============================================================
432	    _loadMapFromCache(id) {
433	      var self = this
434	      return new Promise(function(resolve) {
435	        try {
436	          var engine = global.searchEngine
437	          if (!engine) {
438	            resolve(false)
439	            return
440	          }
441	
442	          var mapChunkSize = global.mapChunkSize || 100
443	          var mapId = Math.floor(id / mapChunkSize)
444	
445	          // 检查是否已经在内存中
446	          if (engine.mapData && engine.mapData[mapId]) {
447	            resolve(true)
448	            return
449	          }
450	
451	          // 从 storage 读取缓存
452	          var storageModule = require('@system.storage')
453	          var cacheKey = engine._getMapCacheKey ? engine._getMapCacheKey(mapId) : ('search_engine_map_v1_' + mapId)
454	
455	          storageModule.get({
456	            key: cacheKey,
457	            success: function(data) {
458	              try {
459	                var mapData = JSON.parse(data)
460	                if (!engine.mapData) engine.mapData = {}
461	                engine.mapData[mapId] = mapData
462	                if (typeof global.addRuntimeLog === 'function') {
463	                  global.addRuntimeLog('[detail] 从缓存加载 Map ' + mapId + ' 成功', 'success')
464	                }
465	                resolve(true)
466	              } catch(e) {
467	                resolve(false)
468	              }
469	            },
470	            fail: function() {
471	              resolve(false)
472	            }
473	          })
474	        } catch(e) {
475	          resolve(false)
476	        }
477	      })
478	    },
479	
480	    // ============================================================
481	    // 直接读 Map 文件（兜底）
482	    // ============================================================
483	    _readMapFileDirectly(id) {
484	      var self = this
485	      return new Promise(function(resolve) {
486	        try {
487	          var file = require('@system.file')
488	          var mapChunkSize = global.mapChunkSize || 100
489	          var chunkIndex = Math.floor(id / mapChunkSize)
490	          var mapPath = '/common/map_' + chunkIndex + '.txt'
491	
492	          file.readText({
493	            uri: mapPath,
494	            success: function(data) {
495	              try {
496	                var lines = data.text.split('\n').filter(function(line) { return line.trim() })
497	                for (var i = 0; i < lines.length; i++) {
498	                  var parts = lines[i].split('|')
499	                  if (parts.length < 4) continue
500	                  var mapId = parseInt(parts[0], 10)
501	                  if (mapId === id) {
502	                    resolve({
503	                      id: mapId,
504	                      year: parseInt(parts[1], 10),
505	                      yearDisplay: self._formatYearDisplay(parseInt(parts[1], 10)),
506	                      regionId: parseInt(parts[2], 10),
507	                      region: self._getRegionName(parseInt(parts[2], 10)),
508	                      title: parts[3] || '未知事件'
509	                    })
510	                    return
511	                  }
512	                }
513	                resolve(null)
514	              } catch(e) {
515	                resolve(null)
516	              }
517	            },
518	            fail: function(err, code) {
519	              resolve(null)
520	            }
521	          })
522	        } catch(e) {
523	          resolve(null)
524	        }
525	      })
526	    },
527	
528	    // ============================================================
529	    // 直接读 detail 文件
530	    // ============================================================
531	    _readDetailFileDirectly(id) {
532	      return new Promise(function(resolve) {
533	        try {
534	          var file = require('@system.file')
535	          var chunkSize = global.detailChunkSize || 100
536	          var chunkIndex = Math.floor(id / chunkSize)
537	          var offset = id % chunkSize
538	          var uri = '/common/detail_' + chunkIndex + '.txt'
539	
540	          file.readText({
541	            uri: uri,
542	            success: function(data) {
543	              try {
544	                var lines = data.text.split('\n')
545	                if (offset >= lines.length) {
546	                  resolve(null)
547	                  return
548	                }
549	                var parts = lines[offset].split('|')
550	                if (parts.length < 4) {
551	                  resolve(null)
552	                  return
553	                }
554	                var restStr = parts[1] || ''
555	                var restKeywords = restStr.split(',').filter(function(k) {
556	                  return k && k.trim() !== ''
557	                })
558	                resolve({
559	                  restKeywords: restKeywords,
560	                  cause: parts[2] || '',
561	                  impact: parts[3] || ''
562	                })
563	              } catch(e) {
564	                resolve(null)
565	              }
566	            },
567	            fail: function(err, code) {
568	              resolve(null)
569	            }
570	          })
571	        } catch(e) {
572	          resolve(null)
573	        }
574	      })
575	    },
576	
577	    // ============================================================
578	    // 获取地区名称
579	    // ============================================================
580	    _getRegionName(regionId) {
581	      var regionList = global.searchEngine ? global.searchEngine.getRegionList() : []
582	      var regionMap = {
583	        'asia': '亚洲',
584	        'europe': '欧洲',
585	        'africa': '非洲',
586	        'north_america': '北美洲',
587	        'south_america': '南美洲',
588	        'other': '其他'
589	      }
590	      var tag = (regionList && regionList[regionId]) ? regionList[regionId] : '未知'
591	      return regionMap[tag] || tag
592	    },
593	
594	    // ============================================================
595	    // 收藏功能
596	    // ============================================================
597	    checkFavoriteStatus(id) {
598	      var self = this
599	      storage.get({
600	        key: 'favorite_list',
601	        success: function(data) {
602	          try {
603	            var favorites = JSON.parse(data) || []
604	            var found = false
605	            for (var i = 0; i < favorites.length; i++) {
606	              var item = favorites[i]
607	              var itemId = (typeof item === 'number') ? item : (item.id || 0)
608	              if (itemId === id) {
609	                found = true
610	                break
611	              }
612	            }
613	            self.isFavorited = found
614	          } catch(e) {
615	            self.isFavorited = false
616	          }
617	        },
618	        fail: function() {
619	          self.isFavorited = false
620	        }
621	      })
622	    },
623	
624	    toggleFavorite() {
625	      var self = this
626	
627	      if (this.eventId === undefined || this.eventId === null) {
628	        prompt.showToast({ message: '错误：事件ID无效', duration: 1000 })
629	        return
630	      }
631	
632	      var currentId = this.eventId
633	      var wasFavorited = this.isFavorited
634	
635	      var favoriteItem = {
636	        id: currentId,
637	        yearDisplay: this.yearDisplay || '未知',
638	        title: this.detailTitle || (this.keywordList && this.keywordList.length > 0 ? this.keywordList[0] : '未知事件'),
639	        region: this.displayRegion || '未知'
640	      }
641	
642	      storage.get({
643	        key: 'favorite_list',
644	        success: function(data) {
645	          var favorites = []
646	          try {
647	            favorites = JSON.parse(data) || []
648	          } catch(e) {
649	            favorites = []
650	          }
651	
652	          if (wasFavorited) {
653	            var newFavorites = []
654	            for (var i = 0; i < favorites.length; i++) {
655	              var item = favorites[i]
656	              var itemId = (typeof item === 'number') ? item : (item.id || 0)
657	              if (itemId !== currentId) {
658	                newFavorites.push(item)
659	              }
660	            }
661	            storage.set({
662	              key: 'favorite_list',
663	              value: JSON.stringify(newFavorites),
664	              success: function() {
665	                self.isFavorited = false
666	                prompt.showToast({ message: '已取消收藏', duration: 500 })
667	                if (typeof global.addRuntimeLog === 'function') {
668	                  global.addRuntimeLog('取消收藏成功: ID=' + currentId, 'info')
669	                }
670	              },
671	              fail: function() {
672	                prompt.showToast({ message: '取消收藏失败', duration: 500 })
673	              }
674	            })
675	          } else {
676	            var exists = false
677	            for (var i = 0; i < favorites.length; i++) {
678	              var item = favorites[i]
679	              var itemId = (typeof item === 'number') ? item : (item.id || 0)
680	              if (itemId === currentId) {
681	                exists = true
682	                break
683	              }
684	            }
685	            if (!exists) {
686	              favorites.push(favoriteItem)
687	            }
688	            storage.set({
689	              key: 'favorite_list',
690	              value: JSON.stringify(favorites),
691	              success: function() {
692	                self.isFavorited = true
693	                prompt.showToast({ message: '已添加收藏', duration: 500 })
694	                if (typeof global.addRuntimeLog === 'function') {
695	                  global.addRuntimeLog('添加收藏成功: ID=' + currentId, 'info')
696	                }
697	              },
698	              fail: function() {
699	                prompt.showToast({ message: '添加收藏失败', duration: 500 })
700	              }
701	            })
702	          }
703	        },
704	        fail: function() {
705	          if (!wasFavorited) {
706	            var favorites = [favoriteItem]
707	            storage.set({
708	              key: 'favorite_list',
709	              value: JSON.stringify(favorites),
710	              success: function() {
711	                self.isFavorited = true
712	                prompt.showToast({ message: '已添加收藏', duration: 500 })
