import router from '@system.router'

export default {
  private: {
    time: '00:00',
    timeTimer: null,
    categories: [
      { name: '健康', icon: '/common/icons/health.png' },
      { name: '科学', icon: '/common/icons/science.png' },
      { name: '历史', icon: '/common/icons/history.png' },
      { name: '生活', icon: '/common/icons/life.png' },
      { name: '急救', icon: '/common/icons/aid.png' },
      { name: '运动', icon: '/common/icons/sport.png' }
    ]
  },

  onInit() {
    this.updateTime()
    this.timeTimer = setInterval(() => { this.updateTime() }, 30000)
  },

  onDestroy() {
    if (this.timeTimer) clearInterval(this.timeTimer)
  },

  updateTime() {
    var now = new Date()
    var h = now.getHours().toString().padStart(2, '0')
    var m = now.getMinutes().toString().padStart(2, '0')
    this.time = h + ':' + m
  },

  goSearch() {
    router.push({ uri: '/pages/result' })
  },

  goCategory(cat) {
    global.searchCategory = cat
    router.push({ uri: '/pages/result' })
  },

  goSettings() {
    router.push({ uri: '/pages/settings' })
  }
}
